import math


def _integers_strictly_between(a, b):
    """Return the number of integers strictly between ``a`` and ``b``."""
    low, high = (a, b) if a <= b else (b, a)
    return max(0, math.ceil(high) - math.floor(low) - 1)


def count_Intgral_Points(x1, y1, x2, y2):
    """Write a python function to count the number of integral co-ordinates that lie inside a square.

    ``(x1, y1)`` and ``(x2, y2)`` are opposite corners of the
    (axis-aligned) square. Points on the boundary are not counted,
    so the result is the number of integers strictly between the
    x-coordinates multiplied by the number strictly between the
    y-coordinates.
    """
    return _integers_strictly_between(x1, x2) * _integers_strictly_between(y1, y2)
